import js from '@eslint/js';
import globals from 'globals';
import reactHooks from 'eslint-plugin-react-hooks';
import reactRefresh from 'eslint-plugin-react-refresh';
import tseslint from 'typescript-eslint';

export default tseslint.config(
  { ignores: ['dist'] },
  {
    extends: [js.configs.recommended, ...tseslint.configs.recommended],
    files: ['**/*.{ts,tsx}'],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
    },
    plugins: {
      'react-hooks': reactHooks,
      'react-refresh': reactRefresh,
    },
    rules: {
      ...reactHooks.configs.recommended.rules,
      'react-refresh/only-export-components': [
        'warn',
        { allowConstantExport: true },
      ],
    },
  }
);

{
  "compilerOptions": {
    "target": "ES2022",
    "lib": ["ES2023"],
    "module": "ESNext",
    "skipLibCheck": true,

    /* Bundler mode */
    "moduleResolution": "bundler",
    "allowImportingTsExtensions": true,
    "isolatedModules": true,
    "moduleDetection": "force",
    "noEmit": true,

    /* Linting */
    "strict": true,
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "noFallthroughCasesInSwitch": true
  },
  "include": ["vite.config.ts"]
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  optimizeDeps: {
    exclude: ['lucide-react'],
  },
});

import { AbsoluteFill, Sequence, useCurrentFrame, spring, Composition, Audio } from 'remotion';
import { Brain, Sparkles, Book, Newspaper, Lightbulb } from 'lucide-react';

const FRAME_PER_SEGMENT = 120;

type ContentType = 'facts' | 'story' | 'news';

const defaultContent = {
  facts: [
    "The human brain processes images 60,000 times faster than text",
    "A day on Venus is longer than its year",
    "Honey never spoils. Archaeologists found 3000-year-old honey still preserved",
    "Octopuses have three hearts"
  ],
  story: [
    "Once upon a time in a digital realm...",
    "The characters embarked on an adventure...",
    "They faced unexpected challenges...",
    "Finally, they emerged transformed..."
  ],
  news: [
    "Breaking: Major Discovery Announced",
    "Experts Weigh In on Implications",
    "Global Response Develops",
    "Analysis: What This Means for the Future"
  ]
};

const CONTENT_CONFIG: Record<ContentType, {
  icon: typeof Brain;
  title: string;
  gradient: string;
  music: string;
}> = {
  facts: {
    icon: Lightbulb,
    title: "Did you know?",
    gradient: "from-blue-500/20 to-purple-600/20",
    music: "https://cdn.pixabay.com/download/audio/2024/12/19/audio_ffb1cdd708.mp3?filename=motivation-hi-tech-278535.mp3"
  },
  story: {
    icon: Book,
    title: "Story Time",
    gradient: "from-emerald-500/20 to-teal-600/20",
    music: "https://cdn.pixabay.com/download/audio/2025/01/13/audio_cb530e8a4c.mp3?filename=dream-284878.mp3"
  },
  news: {
    icon: Newspaper,
    title: "Breaking News",
    gradient: "from-red-500/20 to-orange-600/20",
    music: "https://cdn.pixabay.com/download/audio/2023/06/16/audio_000a68ef8b.mp3?filename=breaking-news-intro-logo-154189.mp3"
  }
};

const ContentCard: React.FC<{ content: string; type: ContentType }> = ({ content, type }) => {
  const frame = useCurrentFrame();
  const config = CONTENT_CONFIG[type];
  const Icon = config.icon;

  const entrance = spring({
    frame,
    fps: 30,
    from: 0,
    to: 1,
    config: {
      damping: 12,
    },
  });

  const textReveal = spring({
    frame: frame - 15,
    fps: 30,
    from: 0,
    to: 1,
    config: {
      damping: 15,
    },
  });

  const iconSpin = spring({
    frame,
    fps: 30,
    from: -180,
    to: 0,
    config: {
      damping: 12,
    },
  });

  const imageReveal = spring({
    frame: frame - 30,
    fps: 30,
    from: 0,
    to: 1,
    config: {
      damping: 15,
    },
  });

  const sparkleFloat = Math.sin(frame / 10) * 10;

  // Generate image URL based on the content
  const imageUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(content)}?width=800&height=600&nologo=true`;

  return (
    <AbsoluteFill className="flex items-center justify-center">
      <div className="relative w-full h-full flex flex-col items-center justify-center px-8">
        <div className={`absolute inset-0 bg-gradient-to-b ${config.gradient}`} />

        {/* Background Image with Overlay */}
        <div 
          className="absolute inset-0 z-0"
          style={{
            opacity: imageReveal * 0.3,
          }}
        >
          <img
            src={imageUrl}
            alt=""
            className="w-full h-full object-cover"
            style={{
              filter: 'blur(10px)',
            }}
          />
          <div className={`absolute inset-0 bg-gradient-to-b ${config.gradient.replace('/20', '/80')}`} />
        </div>

        <div 
          style={{
            opacity: entrance,
            transform: `scale(${entrance})`,
          }}
          className="relative z-10 w-full"
        >
          <div className="flex justify-center mb-8">
            <div
              style={{
                transform: `rotate(${iconSpin}deg)`,
              }}
              className="bg-blue-500 p-6 rounded-2xl shadow-lg"
            >
              <Icon className="w-12 h-12 text-white" />
            </div>
          </div>

          <div 
            style={{
              transform: `translateY(${sparkleFloat}px)`,
            }}
            className="absolute top-4 right-4"
          >
            <Sparkles className="w-8 h-8 text-yellow-400" />
          </div>

          <div className="bg-white/90 backdrop-blur-sm rounded-3xl p-8 shadow-2xl mx-4
                        border-2 border-white/20">
            <h2 
              style={{
                opacity: textReveal,
                transform: `translateY(${(1 - textReveal) * 20}px)`,
              }}
              className="text-4xl font-bold text-center text-gray-800 mb-6"
            >
              {config.title}
            </h2>
            <p 
              style={{
                opacity: textReveal,
                transform: `translateY(${(1 - textReveal) * 20}px)`,
              }}
              className="text-3xl text-center text-gray-700 leading-relaxed mb-6"
            >
              {content}
            </p>

            {/* AI Generated Image */}
            <div
              style={{
                opacity: imageReveal,
                transform: `translateY(${(1 - imageReveal) * 20}px)`,
              }}
              className="rounded-xl overflow-hidden shadow-lg"
            >
              <img
                src={imageUrl}
                alt={content}
                className="w-full h-[50rem] object-cover"
              />
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

interface ContentVideoProps {
  content?: string[];
  contentType: ContentType;
}

export const ContentVideo: React.FC<ContentVideoProps> = ({ 
  content = defaultContent.facts,
  contentType = 'facts'
}) => {
  const currentContent = content.length > 0 ? content : defaultContent[contentType];
  const config = CONTENT_CONFIG[contentType];

  return (
    <AbsoluteFill className="bg-gradient-to-br from-indigo-600 to-purple-800">
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(255,255,255,0.1)_0%,_transparent_70%)]" />

      {/* Background Music */}
      <Audio
        src={config.music}
        volume={0.3}
        startFrom={0}
      />

      {currentContent.map((segment, index) => (
        <Sequence
          key={index}
          from={index * FRAME_PER_SEGMENT}
          durationInFrames={FRAME_PER_SEGMENT}
        >
          <ContentCard content={segment} type={contentType} />
        </Sequence>
      ))}
    </AbsoluteFill>
  );
};

export const RemotionVideo: React.FC = () => {
  return (
    <Composition
      id="ContentVideo"
      component={ContentVideo}
      durationInFrames={4 * FRAME_PER_SEGMENT}
      fps={30}
      width={1080}
      height={1920}
    />
  );
};

import { Player } from '@remotion/player';
import { useState } from 'react';
import { Search, Loader2, Book, Newspaper, Lightbulb } from 'lucide-react';
import { ContentVideo } from './Video';

type ContentType = 'facts' | 'story' | 'news';

const SYSTEM_PROMPTS: Record<ContentType, string> = {
  facts: 'You are a facts generator AI. Always respond with facts in the following format:\n[\n  "Fact 1",\n  "Fact 2",\n  "Fact 3",\n  "Fact 4"\n]\nYou can replace "Fact 1", "Fact 2", "Fact 3", and "Fact 4" with actual facts as needed.',
  story: 'You are a storyteller AI. Always respond with story segments in the following format:\n[\n  "Once upon a time...",\n  "As the story continued...",\n  "Then something unexpected happened...",\n  "Finally..."\n]\nCreate an engaging short story broken into 4 parts.',
  news: 'You are a news reporter AI. Always respond with news headlines and details in the following format:\n[\n  "Breaking: Main Headline",\n  "Key Development 1",\n  "Important Update",\n  "Latest Analysis"\n]\nCreate a news report broken into 4 segments.'
};

const TEMPLATE_INFO = {
  facts: {
    icon: Lightbulb,
    label: 'Facts',
    placeholder: 'Enter a topic for facts...'
  },
  story: {
    icon: Book,
    label: 'Story',
    placeholder: 'Enter a theme or topic for a story...'
  },
  news: {
    icon: Newspaper,
    label: 'News',
    placeholder: 'Enter a subject for news coverage...'
  }
} as const;

const App = () => {
  const [prompt, setPrompt] = useState('');
  const [content, setContent] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [contentType, setContentType] = useState<ContentType>('facts');

  const generateContent = async () => {
    if (!prompt.trim()) return;

    setLoading(true);
    try {
      const response = await fetch(
        `https://text.pollinations.ai/${encodeURIComponent(prompt)}?system=${encodeURIComponent(SYSTEM_PROMPTS[contentType])}&model=searchgpt`
      );
      const data = await response.text();
      try {
        const parsedContent = JSON.parse(data);
        if (Array.isArray(parsedContent) && parsedContent.length >= 4) {
          setContent(parsedContent.slice(0, 4));
        }
      } catch (e) {
        console.error('Failed to parse content:', e);
      }
    } catch (error) {
      console.error('Error generating content:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-gray-800 p-8">
      <div className="max-w-sm grid grid-cols-1 mx-auto space-y-6">
        <h1 className="text-3xl font-bold text-white mb-6">AI Video Generator</h1>

        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-4 shadow-xl space-y-4">
          {/* Template Selector */}
          <div className="grid grid-cols-3 gap-2">
            {(Object.entries(TEMPLATE_INFO) as [ContentType, typeof TEMPLATE_INFO[keyof typeof TEMPLATE_INFO]][]).map(([type, info]) => {
              const Icon = info.icon;
              return (
                <button
                  key={type}
                  onClick={() => setContentType(type)}
                  className={`flex flex-col items-center p-3 rounded-lg transition-colors ${
                    contentType === type
                      ? 'bg-blue-500 text-white'
                      : 'bg-white/5 text-gray-300 hover:bg-white/10'
                  }`}
                >
                  <Icon className="w-6 h-6 mb-2" />
                  <span className="text-sm font-medium">{info.label}</span>
                </button>
              );
            })}
          </div>

          {/* Input Field */}
          <div className="relative">
            <input
              type="text"
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder={TEMPLATE_INFO[contentType].placeholder}
              className="w-full bg-white/10 text-white placeholder-gray-400 rounded-lg px-4 py-3 pr-12 focus:outline-none focus:ring-2 focus:ring-blue-500"
              onKeyDown={(e) => e.key === 'Enter' && generateContent()}
            />
            <button
              onClick={generateContent}
              disabled={loading}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-lg bg-blue-500 hover:bg-blue-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? (
                <Loader2 className="w-5 h-5 text-white animate-spin" />
              ) : (
                <Search className="w-5 h-5 text-white" />
              )}
            </button>
          </div>
        </div>
          {
            prompt && <span className='text-red-500 text-center'>Images may take sometime!</span>
          }

        <div className="aspect-[9/16] bg-white/5 rounded-2xl shadow-2xl overflow-hidden">
          <Player
            component={ContentVideo}
            durationInFrames={480}
            compositionWidth={1080}
            compositionHeight={1920}
            fps={30}
            controls
            style={{
              width: '100%',
              height: '100%'
            }}
            inputProps={{
              content: content.length > 0 ? content : undefined,
              contentType
            }}
          />
        </div>
      </div>
    </div>
  );
}

export default App;

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.tsx';
import './index.css';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>
);
